import fs from 'node:fs';import path from 'node:path';import assert from 'node:assert/strict';import {execFileSync} from 'node:child_process';import {createHash} from 'node:crypto';
const root=process.cwd(),P='plans/260925-documentation-authority-unification/',R=P+'reports/phase-06/';
const gen=await import(root+'/scripts/generate-doc-inventory.mjs');const cs=await import(root+'/scripts/check-doc-candidate-status.mjs');const con=await import(root+'/scripts/check-doc-constitution.mjs');
const a=JSON.parse(fs.readFileSync(R+'step7-carriage-accounting.json'));const triage=JSON.parse(fs.readFileSync(R+'step7-triage.json'));const scan=JSON.parse(fs.readFileSync(R+'liveness-proposals-redesigns.json'));const diffs=JSON.parse(fs.readFileSync(R+'step7-differing-digests.json'));
const sha=s=>createHash('sha256').update(s).digest('hex');const git=(...args)=>execFileSync('git',args,{encoding:'utf8',maxBuffer:32e6});
assert.equal(sha(fs.readFileSync(R+'working-identity-registry.json')),a.registryInputSha256);git('merge-base','--is-ancestor',a.sourceCommit,'HEAD');
const constitution=JSON.parse(fs.readFileSync(P+'minimum-constitution.json'));const vocabulary=JSON.parse(fs.readFileSync(P+'claim-and-disposition-vocabulary.json'));const dispositions=new Map(vocabulary.sourceDispositions.map(d=>[d.id,d]));const knownKinds=new Set(vocabulary.claimKinds.map(k=>k.id));
const ids=new Set();const fileProofs=[];let rows=0,differing=0,literalUnits=0,linkRebases=0;
for(const f of a.files){
 const source=fs.readFileSync(f.source,'utf8'),target=fs.readFileSync(f.target,'utf8');assert.equal(source,git('show',a.sourceCommit+':'+f.source));assert.equal(sha(source),f.sourceSha256);assert.equal(sha(target),f.targetSha256);
 const sl=source.split('\n'),tl=target.split('\n');const reconstructed=[];for(const m of f.sourceLineMap){let l=tl[m.targetLine-1];for(const rebase of f.relativeLinkRebases.filter(x=>x.sourceLine===m.sourceLine).reverse())l=l.replace(rebase.to,rebase.from);reconstructed[m.sourceLine-1]=l;}assert.equal(reconstructed.join('\n'),source);
 for(const rebase of f.relativeLinkRebases){const bare=s=>s.split(/[?#]/)[0];assert.equal(path.posix.normalize(path.posix.join(path.posix.dirname(f.source),bare(rebase.from))),rebase.repositoryReferent);assert.equal(path.posix.normalize(path.posix.join(path.posix.dirname(f.target),bare(rebase.to))),rebase.repositoryReferent);}
 const su=gen.extractMarkdownConservationUnits(source),tu=gen.extractMarkdownConservationUnits(target);const shard=JSON.parse(fs.readFileSync(f.shard));assert.equal(shard.claims.length,su.length);assert.equal(shard.sources.length,1);assert.equal(shard.sources[0],f.source);assert.equal(tu.filter(u=>u.unitKind==='heading'&&u.level===1).length,1);assert.equal(con.classifyPath(f.target,constitution).kind,f.kind);assert.equal(shard.files[0].disposition,f.rowDisposition);assert(dispositions.get(f.rowDisposition).allowedFileClasses.includes(f.sourceFileClass));
 for(const row of shard.claims){assert(!ids.has(row.claimId));ids.add(row.claimId);assert.equal(row.reviewStatus,'pending');assert.equal(row.authoredBy,a.authorSession);assert.equal(row.disposition,f.rowDisposition);assert.equal(row.targetOwner,f.target);assert(knownKinds.has(row.claimKind));assert(!Object.keys(row).some(k=>k.startsWith('reviewed')||k.startsWith('reviewReport')));
 const account=f.claims.find(c=>c.claimId===row.claimId);const s=su.find(u=>u.anchor===account.sourceAnchor),t=tu.find(u=>u.anchor===row.targetAnchor);assert.equal(row.sourceUnitDigest,s.textDigest);assert.equal(row.targetUnitDigest,t.textDigest);assert.equal(row.sourceUnitDigest,account.sourceUnitDigest);assert.equal(row.targetUnitDigest,account.targetUnitDigest);assert.equal(row.sourceUnitDigest!==row.targetUnitDigest,account.differingDigest);rows++;if(account.differingDigest)differing++;
 }
 const list=diffs.files.find(x=>x.source===f.source);assert.deepEqual(list.mandatoryDifferingDigestRows.map(c=>c.claimId).sort(),f.differingDigestClaimIds.toSorted());assert.equal(list.sourceRows,shard.claims.length);
 const sf=scan.files.find(x=>x.path===f.source);assert.equal(sf.sourceBlob,f.sourceBlob);assert.equal(sf.authorAdjudication.target,f.target);assert(sf.sections.length);const sections=sf.sections.toSorted((x,y)=>x.startLine-y.startLine);assert.equal(sections[0].startLine,1);for(let i=1;i<sections.length;i++)assert.equal(sections[i].startLine,sections[i-1].endLine+1);
 literalUnits+=f.literalSourceUnits.length;linkRebases+=f.relativeLinkRebases.length;
 fileProofs.push({source:f.source,target:f.target,sourceBlob:f.sourceBlob,sourceSha256:f.sourceSha256,targetSha256:f.targetSha256,rows:shard.claims.length,sourceLineRecovery:true,exactSourceUnchanged:true,fullUnitBindings:true,allPending:true,actualKind:f.kind,mapKind:f.mapKind,triageDisposition:f.triageDisposition,rowDisposition:f.rowDisposition,literalUnits:f.literalSourceUnits.length,differingDigestRows:f.differingDigestClaimIds.length});
}
assert.equal(rows,a.totals.claims);assert.equal(differing,a.totals.differingDigests);assert.equal(a.files.length,20);assert.equal(triage.files.length,20);
// Metadata/placement APIs use explicit working-tree files: no native inventory/sync, tracked-file omission or persistence.
const metadata=cs.checkCandidateMetadata({files:a.files.map(f=>f.target),readFile:f=>fs.readFileSync(f,'utf8'),switchboard:JSON.parse(fs.readFileSync(P+'transitional-switchboard.json')),constitution,repoRoot:root});assert.deepEqual(metadata.findings,[]);assert.equal(metadata.counts.checked,20);
const trackedChanges=git('diff','--name-only').trim().split('\n').filter(Boolean);assert(trackedChanges.every(p=>[R+'progress.md',R+'owner-queue.md'].includes(p)),trackedChanges.join('\n'));
const status=git('status','--porcelain','--untracked-files=all').split('\n').filter(Boolean);assert(status.every(line=>{const f=line.slice(3);return f.startsWith('docs/')||f.startsWith(P);}));assert.equal(git('rev-list','--count','main','--not','69dd3ee7f').trim(),'0');
const result={version:1,sourceCommit:a.sourceCommit,verifiedAt:new Date().toISOString(),rows,pending:rows,reviewed:0,authorRemaining:0,files:20,dispositions:{placeVerbatimFiles:15,archiveWithReasonFiles:5,deleteFiles:0},classes:a.totals.classes,differingDigests:differing,literalUnits,linkRebases,allSourceLinesRecovered:true,sourcePathsUnchanged:true,persistedRegistryUnchanged:true,persistedRegistrySha256:a.registryInputSha256,persistedRegistryBytes:fs.statSync(R+'working-identity-registry.json').size,metadata,trackedChanges,writeScopeValid:true,noMainCommitsBeyondLastSync:true,fileProofs,limitations:['Local committed-source and working-target proof only; no full native sync or D/E certification','All 1815 source decisions pending independent review; no approval created','Frozen map collection-index at platform proposals root actually classifies proposal; explicitly owed to independent navigation review','The generated knowledge skill header names domains/coding/skills, not the absent core/skills source named in the assignment','Full truth, native gaps/identities, bounded review packs, samples, hostile review and promotion/cutover remain owed']};
fs.writeFileSync('/tmp/fgos-work/step7-verification.json',JSON.stringify(result,null,2)+'\n');console.log(JSON.stringify({rows,pending:rows,differing,literalUnits,linkRebases,metadata:metadata.counts,registryUnchanged:true,scope:true}));
